int check_media_change(struct cdrom_device_info *cdi, unsigned long arg) {
    int ret = -ENOSYS;
    struct cdrom_changer_info *info = NULL;

    if (!cdi || !cdrom_can_eject(cdi)) {
        return -EINVAL;
    }

    if (arg > CDROM_MAX_DISC) {
        return -EINVAL;
    }

    info = kmalloc(sizeof(*info), GFP_KERNEL);
    if (!info) {
        return -ENOMEM;
    }

    ret = cdrom_get_changer_info(cdi, info);
    if (ret < 0) {
        goto out;
    }

    if (arg == CDROM_CURRENT_DISC) {
        ret = (info->discs_present & (1 << info->current_disc)) ? 0 : -ENOMEDIUM;
    } else {
        ret = (info->discs_present & (1 << arg)) ? 0 : -ENOMEDIUM;
    }

out:
    kfree(info);
    return ret;
}
